class Solution {
public:
    string removeOuterParentheses(string s) {
        string res;
        int balance = 0, start = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            balance += (s[i] == '(') ? 1 : -1;
            if (balance == 0) {
                res.append(s, start + 1, i - start - 1);
                start = i + 1;
            }
        }
        return res;
    }
};

